// Minimal argparse-style parser for the three required options
// --key, --iv, --data. Supports "--name value" and "--name=value".
// On error: argparse-style message to stderr, exit code 2.

const PROG = 'test17.mjs';
const OPTIONS = ['key', 'iv', 'data'];

function usage() {
  return `usage: ${PROG} [-h] --key KEY --iv IV --data DATA`;
}

function fail(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  const result = {};
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    let name = null;
    let value = null;

    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        name = arg.slice(2, eq);
        value = arg.slice(eq + 1);
      } else {
        name = arg.slice(2);
      }
    }

    if (name === null || !OPTIONS.includes(name)) {
      fail(`unrecognized arguments: ${arg}`);
    }

    if (value === null) {
      if (i + 1 >= argv.length) {
        fail(`argument --${name}: expected one argument`);
      }
      value = argv[++i];
    }
    result[name] = value;
  }

  const missing = OPTIONS.filter((n) => result[n] === undefined);
  if (missing.length > 0) {
    fail(
      'the following arguments are required: ' +
        missing.map((n) => `--${n}`).join(', ')
    );
  }

  return { key: result.key, iv: result.iv, data: result.data };
}

