import { bytesRepr } from '/output/pyrepr.mjs';
import { parseArgs } from '/output/args.mjs';

let failures = 0;
function eq(actual, expected, label) {
  if (actual === expected) {
    console.log(`ok   ${label}: ${actual}`);
  } else {
    failures++;
    console.log(`FAIL ${label}: got ${JSON.stringify(actual)}, want ${JSON.stringify(expected)}`);
  }
}

// --- bytesRepr ---
eq(bytesRepr(new Uint8Array([])), "b''", 'empty');
eq(bytesRepr(new Uint8Array([39])), `b"'"`, 'single quote only -> double quotes');
eq(bytesRepr(new Uint8Array([39, 34])), `b'\\'"'`, 'both quotes -> b\' with escaped single');
eq(bytesRepr(new Uint8Array([34])), `b'"'`, 'double quote only -> single quotes, unescaped');
eq(bytesRepr(new Uint8Array([0x0c, 0x2b, 0x32, 0xbe])), `b'\\x0c+2\\xbe'`, 'mixed escapes');
eq(bytesRepr(new Uint8Array([9, 10, 13])), `b'\\t\\n\\r'`, 'tab/newline/cr');
eq(bytesRepr(new Uint8Array([0x5c])), `b'\\\\'`, 'backslash');
eq(bytesRepr(new Uint8Array([0x20, 0x7e, 0x7f, 0x1f, 0x00, 0xff])), `b' \\x7e\\x7f\\x1f\\x00\\xff'`.replace('\\x7e', '~'), 'boundaries');
eq(bytesRepr(new Uint8Array([104, 101, 108, 108, 111])), `b'hello'`, 'plain ascii');
eq(bytesRepr(new Uint8Array([0xab, 0x0b])), `b'\\xab\\x0b'`, 'lowercase hex, padded');

// --- parseArgs success paths ---
const a = parseArgs(['--key', 'k', '--iv', 'v', '--data', 'd']);
eq(JSON.stringify(a), JSON.stringify({ key: 'k', iv: 'v', data: 'd' }), 'space form');
const b = parseArgs(['--key=k2', '--iv=v2', '--data=d2']);
eq(JSON.stringify(b), JSON.stringify({ key: 'k2', iv: 'v2', data: 'd2' }), 'equals form');
const c = parseArgs(['--data', 'd3', '--key=k3', '--iv', 'v3']);
eq(JSON.stringify(c), JSON.stringify({ key: 'k3', iv: 'v3', data: 'd3' }), 'mixed order/forms');
const d = parseArgs(['--key', '--iv=x', '--iv', 'y', '--data', '']);
eq(d.key, '--iv=x', 'value that looks like a flag is consumed');
eq(d.iv, 'y', 'last occurrence wins');
eq(d.data, '', 'empty value allowed');

console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);

