// Round constants for AES-128 key expansion (10 rounds)
const RCON = new Uint8Array([0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36]);

// Multiply by 2 in GF(2^8) with the AES reduction polynomial 0x11b
function xtime(x) {
  return ((x << 1) ^ (x & 0x80 ? 0x1b : 0x00)) & 0xff;
}

// Multiply by 3 in GF(2^8)
function mul3(x) {
  return xtime(x) ^ x;
}

function subBytes(state) {
  for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]];
}

// State is column-major: byte at row r, col c is state[c * 4 + r].
function shiftRows(state) {
  const t = state.slice();
  // Row 0 unchanged. Row r shifted left by r.
  state[1] = t[5]; state[5] = t[9]; state[9] = t[13]; state[13] = t[1];   // row 1, left 1
  state[2] = t[10]; state[6] = t[14]; state[10] = t[2]; state[14] = t[6]; // row 2, left 2
  state[3] = t[15]; state[7] = t[3]; state[11] = t[7]; state[15] = t[11]; // row 3, left 3
}

function mixColumns(state) {
  for (let c = 0; c < 4; c++) {
    const i = c * 4;
    const a0 = state[i], a1 = state[i + 1], a2 = state[i + 2], a3 = state[i + 3];
    state[i] = xtime(a0) ^ mul3(a1) ^ a2 ^ a3;
    state[i + 1] = a0 ^ xtime(a1) ^ mul3(a2) ^ a3;
    state[i + 2] = a0 ^ a1 ^ xtime(a2) ^ mul3(a3);
    state[i + 3] = mul3(a0) ^ a1 ^ a2 ^ xtime(a3);
  }
}

function addRoundKey(state, roundKeys, offset) {
  for (let i = 0; i < 16; i++) state[i] ^= roundKeys[offset + i];
}

// keyBytes: Uint8Array(16) -> Uint8Array(176) round keys (11 keys of 16 bytes)
export function expandKey(keyBytes) {
  const w = new Uint8Array(176);
  w.set(keyBytes, 0);
  let bytesGenerated = 16;
  let rconIdx = 0;
  const temp = new Uint8Array(4);
  while (bytesGenerated < 176) {
    for (let i = 0; i < 4; i++) temp[i] = w[bytesGenerated - 4 + i];
    if (bytesGenerated % 16 === 0) {
      // RotWord + SubWord + Rcon
      const t = temp[0];
      temp[0] = SBOX[temp[1]] ^ RCON[rconIdx++];
      temp[1] = SBOX[temp[2]];
      temp[2] = SBOX[temp[3]];
      temp[3] = SBOX[t];
    }
    for (let i = 0; i < 4; i++) {
      w[bytesGenerated] = w[bytesGenerated - 16] ^ temp[i];
      bytesGenerated++;
    }
  }
  return w;
}

// block: Uint8Array(16), roundKeys: Uint8Array(176) -> Uint8Array(16) ciphertext
export function encryptBlock(block, roundKeys) {
  const state = block.slice();
  addRoundKey(state, roundKeys, 0);
  for (let round = 1; round <= 9; round++) {
    subBytes(state);
    shiftRows(state);
    mixColumns(state);
    addRoundKey(state, roundKeys, round * 16);
  }
  subBytes(state);
  shiftRows(state);
  addRoundKey(state, roundKeys, 160);
  return state;
}

