import { expandKey, encryptBlock } from '/output/aes-core.mjs';

const hex = (s) => Uint8Array.from(s.match(/../g).map((b) => parseInt(b, 16)));
const toHex = (u8) => Array.from(u8, (b) => b.toString(16).padStart(2, '0')).join('');

const key = hex('000102030405060708090a0b0c0d0e0f');
const pt = hex('00112233445566778899aabbccddeeff');
const expected = '69c4e0d86a7b0430d8cdb78070b4c55a';

const roundKeys = expandKey(key);
if (roundKeys.length !== 176) throw new Error('roundKeys length ' + roundKeys.length);

const ct = encryptBlock(pt, roundKeys);
console.log('ciphertext:', toHex(ct));
console.log('expected  :', expected);
if (toHex(ct) !== expected) {
  console.error('FAIL');
  process.exit(1);
}
// Second FIPS-197 Appendix B key-expansion sanity check: round key 10
const rk10 = '13111d7fe3944a17f307a78b4d2b30c5';
if (toHex(roundKeys.slice(160)) !== rk10) {
  console.error('FAIL round key 10:', toHex(roundKeys.slice(160)));
  process.exit(1);
}
console.log('PASS (FIPS-197 vector + key expansion round 10)');

