// aes-cbc.mjs — AES-128 CBC mode of operation, mirroring pyaes'
// AESModeOfOperationCBC interface. Chaining state is kept across
// encrypt() calls: each plaintext block is XORed with the previous
// ciphertext block (or the IV for the first block) before encryption.

import { expandKey, encryptBlock } from './aes-core.mjs';

export class AESModeOfOperationCBC {
  // key: Uint8Array(16), iv: Uint8Array(16)
  constructor(key, iv) {
    this._roundKeys = expandKey(key);
    this._iv = iv.slice();
  }

  // block: Uint8Array(16) -> Uint8Array(16) ciphertext
  encrypt(block) {
    const xored = new Uint8Array(16);
    for (let i = 0; i < 16; i++) xored[i] = block[i] ^ this._iv[i];
    const cipher = encryptBlock(xored, this._roundKeys);
    this._iv = cipher.slice();
    return cipher;
  }
}

