24	// Round constants for AES-128 key expansion (10 rounds)
25	const RCON = new Uint8Array([0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36]);
26	
27	// Multiply by 2 in GF(2^8) with the AES reduction polynomial 0x11b
28	function xtime(x) {
29	  return ((x << 1) ^ (x & 0x80 ? 0x1b : 0x00)) & 0xff;
30	}
31	
32	// Multiply by 3 in GF(2^8)
33	function mul3(x) {
34	  return xtime(x) ^ x;
35	}
36	
37	function subBytes(state) {
38	  for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]];
39	}
40	
41	// State is column-major: byte at row r, col c is state[c * 4 + r].
42	function shiftRows(state) {
43	  const t = state.slice();
44	  // Row 0 unchanged. Row r shifted left by r.
45	  state[1] = t[5]; state[5] = t[9]; state[9] = t[13]; state[13] = t[1];   // row 1, left 1
46	  state[2] = t[10]; state[6] = t[14]; state[10] = t[2]; state[14] = t[6]; // row 2, left 2
47	  state[3] = t[15]; state[7] = t[3]; state[11] = t[7]; state[15] = t[11]; // row 3, left 3
48	}
49	
50	function mixColumns(state) {
51	  for (let c = 0; c < 4; c++) {
52	    const i = c * 4;
53	    const a0 = state[i], a1 = state[i + 1], a2 = state[i + 2], a3 = state[i + 3];
54	    state[i] = xtime(a0) ^ mul3(a1) ^ a2 ^ a3;
55	    state[i + 1] = a0 ^ xtime(a1) ^ mul3(a2) ^ a3;
56	    state[i + 2] = a0 ^ a1 ^ xtime(a2) ^ mul3(a3);
57	    state[i + 3] = mul3(a0) ^ a1 ^ a2 ^ xtime(a3);
58	  }
59	}
60	
61	function addRoundKey(state, roundKeys, offset) {
62	  for (let i = 0; i < 16; i++) state[i] ^= roundKeys[offset + i];
63	}
64	
65	// keyBytes: Uint8Array(16) -> Uint8Array(176) round keys (11 keys of 16 bytes)
66	export function expandKey(keyBytes) {
67	  const w = new Uint8Array(176);
68	  w.set(keyBytes, 0);
69	  let bytesGenerated = 16;
70	  let rconIdx = 0;
71	  const temp = new Uint8Array(4);
72	  while (bytesGenerated < 176) {
73	    for (let i = 0; i < 4; i++) temp[i] = w[bytesGenerated - 4 + i];
74	    if (bytesGenerated % 16 === 0) {
75	      // RotWord + SubWord + Rcon
76	      const t = temp[0];
77	      temp[0] = SBOX[temp[1]] ^ RCON[rconIdx++];
78	      temp[1] = SBOX[temp[2]];
79	      temp[2] = SBOX[temp[3]];
80	      temp[3] = SBOX[t];
81	    }
82	    for (let i = 0; i < 4; i++) {
83	      w[bytesGenerated] = w[bytesGenerated - 16] ^ temp[i];
84	      bytesGenerated++;
85	    }
86	  }
87	  return w;
88	}
89	
90	// block: Uint8Array(16), roundKeys: Uint8Array(176) -> Uint8Array(16) ciphertext
91	export function encryptBlock(block, roundKeys) {
92	  const state = block.slice();
93	  addRoundKey(state, roundKeys, 0);
94	  for (let round = 1; round <= 9; round++) {
95	    subBytes(state);
96	    shiftRows(state);
97	    mixColumns(state);
98	    addRoundKey(state, roundKeys, round * 16);
99	  }
100	  subBytes(state);
101	  shiftRows(state);
102	  addRoundKey(state, roundKeys, 160);
103	  return state;
104	}

1	// aes-cbc.mjs — AES-128 CBC mode of operation, mirroring pyaes'
2	// AESModeOfOperationCBC interface. Chaining state is kept across
3	// encrypt() calls: each plaintext block is XORed with the previous
4	// ciphertext block (or the IV for the first block) before encryption.
5	
6	import { expandKey, encryptBlock } from './aes-core.mjs';
7	
8	export class AESModeOfOperationCBC {
9	  // key: Uint8Array(16), iv: Uint8Array(16)
10	  constructor(key, iv) {
11	    this._roundKeys = expandKey(key);
12	    this._iv = iv.slice();
13	  }
14	
15	  // block: Uint8Array(16) -> Uint8Array(16) ciphertext
16	  encrypt(block) {
17	    const xored = new Uint8Array(16);
18	    for (let i = 0; i < 16; i++) xored[i] = block[i] ^ this._iv[i];
19	    const cipher = encryptBlock(xored, this._roundKeys);
20	    this._iv = cipher.slice();
21	    return cipher;
22	  }
23	}

1	// Python repr(bytes) for a Uint8Array.
2	// Matches CPython's bytes repr: b'...' by default, b"..." when the data
3	// contains a single quote but no double quote.
4	
5	export function bytesRepr(u8) {
6	  let hasSingle = false;
7	  let hasDouble = false;
8	  for (const b of u8) {
9	    if (b === 0x27) hasSingle = true;
10	    else if (b === 0x22) hasDouble = true;
11	  }
12	  const quote = hasSingle && !hasDouble ? 0x22 : 0x27; // " or '
13	  const q = String.fromCharCode(quote);
14	
15	  let out = 'b' + q;
16	  for (const b of u8) {
17	    if (b === quote || b === 0x5c) {
18	      out += '\\' + String.fromCharCode(b);
19	    } else if (b === 0x09) {
20	      out += '\\t';
21	    } else if (b === 0x0a) {
22	      out += '\\n';
23	    } else if (b === 0x0d) {
24	      out += '\\r';
25	    } else if (b >= 0x20 && b < 0x7f) {
26	      out += String.fromCharCode(b);
27	    } else {
28	      out += '\\x' + b.toString(16).padStart(2, '0');
29	    }
30	  }
31	  return out + q;
32	}

1	// test17.mjs — Node.js ESM port of the pyaes AES-128 CBC script.
2	// Prints each 16-byte ciphertext block via Python's repr(bytes).
3	
4	import { parseArgs } from './args.mjs';
5	import { AESModeOfOperationCBC } from './aes-cbc.mjs';
6	import { bytesRepr } from './pyrepr.mjs';
7	
8	const args = parseArgs(process.argv.slice(2));
9	
10	const aes = new AESModeOfOperationCBC(
11	  Buffer.from(args.key, 'utf8'),
12	  Buffer.from(args.iv, 'utf8')
13	);
14	const data = Buffer.from(args.data, 'utf8');
15	
16	const ciphertexts = [];
17	for (let i = 0; i < data.length; i += 16) {
18	  const cipher = aes.encrypt(data.subarray(i, i + 16));
19	  ciphertexts.push(cipher);
20	}
21	for (const cipher of ciphertexts) {
22	  console.log(bytesRepr(cipher));
23	}

1	// Minimal argparse-style parser for the three required options
2	// --key, --iv, --data. Supports "--name value" and "--name=value".
3	// On error: argparse-style message to stderr, exit code 2.
4	
5	const PROG = 'test17.mjs';
6	const OPTIONS = ['key', 'iv', 'data'];
7	
8	function usage() {
9	  return `usage: ${PROG} [-h] --key KEY --iv IV --data DATA`;
10	}
11	
12	function fail(message) {
13	  process.stderr.write(usage() + '\n');
14	  process.stderr.write(`${PROG}: error: ${message}\n`);
15	  process.exit(2);
16	}
17	
18	export function parseArgs(argv) {
19	  const result = {};
20	  for (let i = 0; i < argv.length; i++) {
21	    const arg = argv[i];
22	    let name = null;
23	    let value = null;
24	
25	    if (arg.startsWith('--')) {
26	      const eq = arg.indexOf('=');
27	      if (eq !== -1) {
28	        name = arg.slice(2, eq);
29	        value = arg.slice(eq + 1);
30	      } else {
31	        name = arg.slice(2);
32	      }
33	    }
34	
35	    if (name === null || !OPTIONS.includes(name)) {
36	      fail(`unrecognized arguments: ${arg}`);
37	    }
38	
39	    if (value === null) {
40	      if (i + 1 >= argv.length) {
41	        fail(`argument --${name}: expected one argument`);
42	      }
43	      value = argv[++i];
44	    }
45	    result[name] = value;
46	  }
47	
48	  const missing = OPTIONS.filter((n) => result[n] === undefined);
49	  if (missing.length > 0) {
50	    fail(
51	      'the following arguments are required: ' +
52	        missing.map((n) => `--${n}`).join(', ')
53	    );
54	  }
55	
56	  return { key: result.key, iv: result.iv, data: result.data };
57	}
